import paramiko
import re
from scp import SCPClient
import time
import os
import functools

from taf.hw.rf_diagnostic_card.exceptions import (
    FHNETConnectionError,
    ExpectedPhraseNotFoundError,
    DownloadFileError,
    FHNETContainerNotFound,
    BTSConnectionError,
    InvalidSourceBtsError,
)


def log_variables_and_time(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        start_time = time.time()
        logger = getattr(self, "logger", None)
        if logger is not None:
            self.logger.debug(f"InvokeShell: Calling function '{func.__name__}' with args: {args} and kwargs: {kwargs}")
        result = func(self, *args, **kwargs)
        if logger is not None:
            self.logger.debug(
                f"InvokeShell: Execution time for function '{func.__name__}': {time.time() - start_time:.2f}s"
            )
            self.logger.debug(f"InvokeShell: Function '{func.__name__}' returned: {result}")
        return result

    return wrapper


class InvokeSshHandler:
    def __init__(
        self, smod_ip="192.168.255.129", username="toor4nsn", password="oZPS0POrRieRtu", logger=None, proxy_vm=None
    ):
        self._smod_ip = smod_ip
        self._smod_username = username
        self._smod_password = password
        self._slave_bts = False
        self._session = None
        self._channel = None
        self._master_bts_alias = None
        self._slave_bts_alias = None
        self.logger = logger
        self._proxy_vm = proxy_vm

    @property
    def session(self):
        """
        SSHClient session
        """
        if self._session is None:
            os.system(f"ssh-keygen -R {self._smod_ip} >/dev/null 2>&1")
            self._session = paramiko.SSHClient()
            self._session.load_system_host_keys()
            self._session.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            if self._proxy_vm is not None:
                proxy_cmd = paramiko.ProxyCommand(
                    "ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "
                    f"{self._proxy_vm['username']}@{self._proxy_vm['ip']} -W {self._smod_ip}:22"
                )
                self.logger.info(f"Connecting to SMOD via proxy VM: {self._proxy_vm['ip']}")
                self._session.connect(
                    hostname=self._smod_ip,
                    username=self._smod_username,
                    password=self._smod_password,
                    sock=proxy_cmd,
                )
            else:
                self._session.connect(
                    hostname=self._smod_ip, username=self._smod_username, password=self._smod_password
                )
            self._master_bts_alias = self._get_master_bts_alias()
            self._slave_bts_alias = None

        return self._session

    @property
    def channel(self):
        """
        Channel connected to the remote shell session on the SSH server
        """
        if self._channel is None:
            self._channel = self.session.invoke_shell()

        return self._channel

    @property
    def master_bts_alias(self):
        """
        Gets master bts alias.
        """
        if self._master_bts_alias is None:
            self._master_bts_alias = self._get_master_bts_alias()

        return self._master_bts_alias

    @property
    def slave_bts_alias(self):
        """
        Gets slave bts alias based on master bts alias.
        """
        if self._slave_bts_alias is None:
            self._slave_bts_alias = self._get_slave_bts_alias(self.master_bts_alias)

        return self._slave_bts_alias

    def _check_session_to_particular_bts_side_and_reconnect_session_if_needed(self, slave_bts):
        """
        Checks if session exists on proper system module side and makes new connection if needed.
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        """
        if slave_bts != self._slave_bts:
            self.close_connection()
            if slave_bts:
                self._connect_to_slave_bts()
            self._slave_bts = slave_bts

    @log_variables_and_time
    def connect_to_fhnet(self, container=None, timeout=2, slave_bts=False):
        """
        Connect to FHNET container through invoke shell terminal
        :param container: FHNET container address to which to connect (0x1018 or 0x2018).
                          Default value is None which means lxc-ls command output will be checked
        :type container: str
        :param timeout: Allowed time in seconds to establish connection. Default is 2s
        :type timeout: int
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        :return: True when connected to FHNET
        :rtype: bool
        :raises FHNETConnectionError exception when connection not established
        """
        self._check_session_to_particular_bts_side_and_reconnect_session_if_needed(slave_bts)

        smod_header = f"root@{self.slave_bts_alias}:" if slave_bts else f"root@{self.master_bts_alias}:"

        ssh_output = self._send_command_and_return_output(command="\r\n", timeout=timeout, expected_phrase="root@")
        if "root@FHNET" not in ssh_output:
            if not container:
                container = self._get_fhnet_container()

            cmd_to_fhnet = f"lxc-attach --name {container}"
            self._send_command_and_return_output(command=cmd_to_fhnet, timeout=timeout, expected_regex=r"root@FHNET")

        self._verify_bts_side_for_connected_container(smod_header)
        self.logger.info("Successfully connected to FHNET")
        return True

    @log_variables_and_time
    def get_file_from_rmod_to_smod(self, filename, smod_path, rmod_path, rmod_ip, username, password):
        """
        Gets file from RMOD to SMOD using FHNET container.
        :param filename: Name with extension of file to get, e.g. "rfsw_package.tar"
        :type filename: str
        :param smod_path: Absolute SMOD path to the directory containing file to be downloaded, e.g. "/ram"
        :type smod_path: str
        :param rmod_path: Absolute RMOD path to directory where file will be downloaded, e.g. "/ram"
        :type rmod_path: str
        :param rmod_ip: RMOD ip address, e.g. "192.168.120.3"
        :type rmod_ip: str
        :param username: RMOD username, e.g. "rfsw"
        :type username: str
        :param password: RMOD password, e.g. "password123"
        :type password: str
        """
        self._download_file_from_rmod_to_fhnet(
            rmod_ip=rmod_ip,
            username=username,
            password=password,
            filename=filename,
            smod_path=smod_path,
            rmod_path=rmod_path,
        )

    @log_variables_and_time
    def download_file_from_smod_to_vm(self, filename, smod_path, local_path, slave_bts=False):
        """
        Downloads file from SMOD to VM via SCP client
        :param filename: name of file to be downloaded (with file extension), e.g. 'file.txt'
        :type filename: str
        :param smod_path: Path on SMOD to directory with file to be downloaded, e.g. '/tmp'
        :type smod_path: str
        :param local_path: Path to local directory where file will be saved, e.g. '/home/ute"
        :type local_path: str
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        """
        source_path = f"{smod_path}/"
        temp_path = "/ram/"
        vm_path = f"{local_path}/"
        remote_master_file = f"{temp_path}{filename}" if slave_bts else f"{source_path}{filename}"
        if slave_bts:
            self._transfer_file_between_master_bts_and_slave_bts(
                source_bts="slave", filename=filename, source_bts_path=source_path, destination_smod_path=temp_path
            )
        self._download_file_from_smod_to_vm(remote_path=remote_master_file, local_path=vm_path, slave_bts=slave_bts)

    @log_variables_and_time
    def _transfer_file_between_master_bts_and_slave_bts(
        self, source_bts, filename, source_bts_path, destination_smod_path, timeout=300
    ):
        """
        Transfers file between modules in fullrack configuration (master and slave) according to defined source bts.
        :param source_bts: name of source bts with file to transfer, "master" or "slave" are possible to set.
        :type source_bts: str
        :param filename: name of file to be transfered (with file extension), e.g. 'file.txt'
        :type filename: str
        :param source_bts_path: path to directory of source smod to transfer file, e.g. '/home/root'.
        :type source_bts_path: str
        :param destination_smod_path: path to directory of destionation smod to transfer file, e.g. '/home/root'.
        :type destination_smod_path: str
        :param timeout: Allowed time in seconds to complete the file transfer. Defaults to 300
        :type timeout: int
        :return: full absolute path to file in destination smod location, e.g.: '/home/root/file.txt'
        :rtype: str
        :raises DownloadFileError: when file transfer was not successfully finished in provided timeout.
        """
        self._check_session_to_particular_bts_side_and_reconnect_session_if_needed(slave_bts=False)
        self._connect_to_smod(slave_bts=False)
        scp_command = self._construct_scp_command(source_bts, filename, source_bts_path, destination_smod_path)
        self.channel.send(scp_command + "\r")
        buff_shell_stdout = ""

        start_time = time.time()
        while time.time() - start_time < timeout:
            shell_stdout = self._recv_data()
            buff_shell_stdout += shell_stdout
            if "(yes/no/[fingerprint])?" in shell_stdout:
                self.channel.send("yes" + "\r")
            elif shell_stdout.lower().endswith("password: "):
                self.channel.send(self._smod_password + "\r")
            elif "100%" in shell_stdout:
                self.logger.info(f"Successfully transferred file from {source_bts} SMOD")
                return f"{destination_smod_path}/{filename}"
            elif "No such file or directory" in shell_stdout:
                raise DownloadFileError(f"No such file or directory after scp: {scp_command} \n {buff_shell_stdout}.")
            time.sleep(0.1)

        raise DownloadFileError(
            f"Couldn't transfer file from {source_bts} SMOD, output from terminal \n {buff_shell_stdout}"
        )

    @log_variables_and_time
    def send_command_and_return_output(
        self,
        command,
        expected_phrase=None,
        timeout=3,
        repetition_interval=0.1,
        slave_bts=False,
    ):
        """
        Sends a command to the invoke shell terminal, waits for response
        checks the outputs contents if expected or unacceptable phrase provided and return output.
        Default behavior, send command and return output from invoke shell terminal.
        :param command: The linux command
        :type command: str
        :param expected_phrase: Phrase to be checked in output from invoke shell terminal, default None
        :type expected_phrase: str
        :param timeout: Allowed time in seconds to execute command. Must be always greater than 0. Default is 3s
        :type timeout: int
        :param repetition_interval: How often in seconds output from invoke shell terminal is checked. Default is 0.1s
        :type repetition_interval: int
        :param slave_bts: Used for fullrack configuration only. True if command should be performed on the slave BTS.
                          Default is False
        :type slave_bts: bool
        :return: Stdout from invoke shell terminal
        :rtype: str
        :raises ExpectedPhraseNotFoundError: when expected phrase was not found in stdout
        """
        self._check_session_to_particular_bts_side_and_reconnect_session_if_needed(slave_bts=slave_bts)
        return self._send_command_and_return_output(
            command=command,
            expected_phrase=expected_phrase,
            timeout=timeout,
            repetition_interval=repetition_interval,
        )

    @log_variables_and_time
    def close_connection(self):
        """
        Terminates ssh session.
        """
        self.session.close()
        self._session, self._channel = None, None

        return self._session

    def _send_command_and_return_output(
        self,
        command,
        expected_phrase=None,
        timeout=3,
        repetition_interval=0.1,
        expected_regex=None,
    ):
        """
        Sends a command to the invoke shell terminal, waits for response
        checks the outputs contents if expected or unacceptable phrase provided and return output.
        Default behavior, send command and return output from invoke shell terminal.
        :param command: The linux command
        :type command: str
        :param expected_phrase: Phrase to be checked in output from invoke shell terminal, default None
        :type expected_phrase: str
        :param timeout: Allowed time in seconds to execute command. Must be always greater than 0. Default is 3s
        :type timeout: int
        :param repetition_interval: How often in seconds output from invoke shell terminal is checked. Default is 0.1s
        :type repetition_interval: int
        :return: Stdout from invoke shell terminal
        :rtype: str or re.Match
        :raises ExpectedPhraseNotFoundError: when expected phrase was not found in stdout
        """
        self.logger.debug(rf"InvokeShell: Sending command: {command}")
        shell_stdout = ""
        self.channel.send(command + "\r")

        while timeout > 0:
            time.sleep(repetition_interval)
            timeout -= repetition_interval
            shell_stdout += self._recv_data()
            if expected_phrase and expected_phrase in shell_stdout:
                return shell_stdout
            if expected_regex and re.search(expected_regex, shell_stdout) is not None:
                return re.search(expected_regex, shell_stdout)

        if (
            expected_phrase
            and expected_phrase not in shell_stdout
            or expected_regex
            and re.search(expected_regex, shell_stdout) is None
        ):
            raise ExpectedPhraseNotFoundError(
                f"Expected phrase '{expected_phrase}' not found in output after cmd: {command}:\n {shell_stdout}"
            )

        return shell_stdout

    @log_variables_and_time
    def _connect_to_slave_bts(self, timeout=2):
        while_loop_timeout = timeout
        ssh_command = (
            f"ssh -o StrictHostKeyChecking=no"
            f" -o UserKnownHostsFile=/dev/null {self._smod_username}@{self.slave_bts_alias}"
        )
        ssh_output = self._send_command_and_return_output(
            command=ssh_command, timeout=timeout, expected_phrase="ssword"
        )
        buff_shell_stdout = ""
        while while_loop_timeout > 0:
            time.sleep(0.1)
            while_loop_timeout -= 0.1
            buff_shell_stdout += ssh_output
            if "password" in ssh_output.lower():
                ssh_output += self._send_command_and_return_output(
                    command=self._smod_password,
                    timeout=timeout,
                    expected_phrase=f"root@{self.slave_bts_alias}:",
                )
                return True
            elif "Could not resolve hostname" in ssh_output:
                raise InvalidSourceBtsError(
                    f"Invalid slave BTS alias: {self.slave_bts_alias}. "
                    f"Check if slave BTS is configured in fullrack setup."
                )
        raise BTSConnectionError(f"Connection to slave BTS failed, output from terminal: {buff_shell_stdout}")

    @log_variables_and_time
    def _connect_to_smod(self, timeout=1, slave_bts=False):
        """
        Connects to smod through invoke shell terminal
        :param timeout: Allowed time in seconds to establish connection. Default is 1s
        :type timeout: int
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection. Defaults to False
        :type slave_bts: bool
        :return: True when connected to smod
        :rtype: bool
        :raises BTSConnectionError exception when connection to BTS (master or slave) failed.
        """
        self._check_session_to_particular_bts_side_and_reconnect_session_if_needed(slave_bts)
        smod_header = f"root@{self.slave_bts_alias}:" if slave_bts else f"root@{self.master_bts_alias}:"

        ssh_output = self._send_command_and_return_output(command="\r\n", timeout=timeout)

        for _ in range(3):
            if smod_header not in ssh_output:
                self._send_command_and_return_output(command="\x03", timeout=timeout)
                ssh_output = self._send_command_and_return_output(command="exit", timeout=timeout)
            else:
                return True
        bts_mode = "slave" if slave_bts else "master"
        raise BTSConnectionError(f"Connection to {bts_mode} BTS failed.")

    def _download_file_from_rmod_to_fhnet(
        self, rmod_ip, username, password, filename, smod_path="/ram", rmod_path="/ram", timeout=300
    ):
        """
        Download file from RMOD to FHNET container through invoke shell terminal
        :param rmod_ip: RMOD ip address
        :type rmod_ip: str
        :param username: RMOD username to set up ssh connection
        :type username: str
        :param password: RMOD password to set up ssh connection
        :type password: str
        :param filename: Name of the downloaded file e.g. RU_12324.zip
        :type filename: str
        :param smod_path: Path where file will be uploaded on FHNET
        :type smod_path: str
        :param rmod_path: Absolute RMOD path to directory where file will be uploaded, e.g. "/ram"
        :type rmod_path: str
        :param timeout: Allowed time in seconds to complete the download. Default is 300s
        :type timeout: int
        :return: Absolute path with filename and extension where it was saved
        :rtype: str
        :raises DownloadFileError exception when no such file or directory after scp command or timeout reached
        """

        scp_command = (
            "scp -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -O "
            f"{username}@{rmod_ip}:{rmod_path}/{filename} {smod_path}/{filename}"
        )
        self.channel.send(scp_command + "\r")
        buff_shell_stdout = ""

        while timeout > 0:
            timeout -= 0.1
            time.sleep(0.1)
            shell_stdout = self._recv_data()
            buff_shell_stdout += shell_stdout
            if "(yes/no/[fingerprint])?" in shell_stdout:
                self.channel.send("yes" + "\r")
            elif shell_stdout.lower().endswith("password: "):
                self.channel.send(password + "\r")
            elif "100%" in shell_stdout:
                self.logger.info(f"Successfully downloaded file from RMOD IP:{rmod_ip} to FHNET")
                return f"{smod_path}/{filename}"
            elif "No such file or directory" in shell_stdout:
                raise DownloadFileError(f"No such file or directory after scp: {scp_command} \n {buff_shell_stdout}")

        raise DownloadFileError(
            f"Couldn't download file from RMOD IP:{rmod_ip} to FHNET, output from terminal \n {buff_shell_stdout}"
        )

    def _download_file_from_smod_to_vm(self, remote_path, local_path, slave_bts=False):
        """
        Download file from SMOD to VM via SCP client
        :param remote_path: Path to the file to be downloaded
        :type remote_path: str
        :param local_path: Path where file will be saved
        :type local_path: str
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        """
        self._check_session_to_particular_bts_side_and_reconnect_session_if_needed(slave_bts=slave_bts)
        with SCPClient(self.session.get_transport()) as sc:
            sc.get(remote_path=remote_path, local_path=local_path, recursive=True)
        self.logger.info("Successfully downloaded file to VM")

    def _get_fhnet_container(self):
        """
        Get FHNET container address executing command on SMOD through invoke shell terminal
        """
        shell_stdout = self._send_command_and_return_output("lxc-ls", expected_regex=r"0x[12]018")
        if not shell_stdout:
            raise FHNETContainerNotFound("FHNET container cannot be found on SMOD!")
        return shell_stdout.group()

    @log_variables_and_time
    def _get_master_bts_alias(self):
        """
        Gets bts alias of master system module based on bts header.
        Examples of bts aliases:
            for ASOx: asc-0a
            for ASIL(left side): fct-0a
            for ASIL(right side): fct-4a
        """
        shell_stdout = self._send_command_and_return_output(command="\r\n", timeout=5, expected_regex=r"root@.*-.a")
        bts_header = shell_stdout.group()
        return bts_header.split("@")[-1]

    def _get_slave_bts_alias(self, master_bts_alias):
        """
        Gets bts alias of slave system module based on master bts alias.
        In case of ASOx there is no slave bts so master bts alias is returned.
        """
        if master_bts_alias == "fct-0a":
            return "fct-4a"
        elif master_bts_alias == "fct-4a":
            return "fct-0a"
        self.logger.error(f"Slave BTS alias cannot be determined from master BTS alias: {master_bts_alias}")
        return master_bts_alias

    def _verify_bts_side_for_connected_container(self, smod_header):
        """
        Verifies if current FHNET container comes from the expected bts side based on given smod header.
        """
        if "-0a" not in smod_header and "-4a" not in smod_header:
            raise BTSConnectionError(f"Unknown SMOD header: {smod_header}")

        fhnet_container = self._get_fhnet_container()

        if "-0a" in smod_header and fhnet_container != "0x1018":
            raise FHNETConnectionError(f"Incorrect container connection for {smod_header}, should be '0x1018'")
        elif "-4a" in smod_header and fhnet_container != "0x2018":
            raise FHNETConnectionError(f"Incorrect container connection for {smod_header}, should be '0x2018'")

    def _construct_scp_command(self, source_bts, filename, source_bts_path, destination_smod_path):
        """
        Constructs the SCP command to transfer a file between master and slave BTS.

        :param source_bts: The source BTS from which the file is to be transferred. Possible values master or slave.
        :type source_bts: str
        :param filename: The name of the file to be transferred, including its extension.
        :type filename: str
        :param source_bts_path: The absolute path on the source BTS where the file is located.
        :type source_bts_path: str
        :param destination_smod_path: The absolute path on the destination SMOD where the file should be transferred.
        :type destination_smod_path: str
        :return: The constructed SCP command as a string.
        :rtype: str
        """
        if source_bts == "master":
            return (
                f"scp {source_bts_path}/{filename} "
                f"{self._smod_username}@{self.slave_bts_alias}:{destination_smod_path}/{filename}"
            )
        elif source_bts == "slave":
            return (
                f"scp {self._smod_username}@{self.slave_bts_alias}:{source_bts_path}/{filename} "
                f"{destination_smod_path}/{filename}"
            )
        raise InvalidSourceBtsError(f"Invalid source BTS provided: {source_bts}")

    def _recv_data(self):
        """
        Receives data from the invoke shell terminal.

        :return: The output received from the invoke shell terminal.
        :rtype: str
        """
        if self.channel.recv_ready():
            shell_stdout = self.channel.recv(9999).decode("utf-8")
            return self._clean_shell_output(shell_stdout)
        return ""

    @staticmethod
    def _clean_shell_output(output):
        ansi_escape = re.compile(r"\x1B[@-_][0-?]*[ -/]*[@-~]")
        output = ansi_escape.sub("", output)
        output = re.sub(r"[\x00-\x1F\x7F-\x9F]", "", output)
        return output
